export const money=(n,d=1)=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',notation:Math.abs(n)>=1e6?'compact':'standard',maximumFractionDigits:d}).format(n);
export const pct=(n,d=1)=>`${(n*100).toFixed(d)}%`;
export function forecastRevenue(start,growths){return growths.reduce((a,g)=>[...a,a.at(-1)*(1+g)],[start]);}
export function dcf({revenue,growths,ebitdaMargins,taxRate,daPct,capexPct,nwcPct,wacc,terminalGrowth,netCash=0,shares=1}){
 const rev=forecastRevenue(revenue,growths); const years=rev.slice(1).map((r,i)=>{const ebitda=r*ebitdaMargins[i],da=r*daPct,ebit=ebitda-da,tax=Math.max(0,ebit*taxRate),capex=r*capexPct,deltaNwc=(r-rev[i])*nwcPct,ufcf=ebit-tax+da-capex-deltaNwc,discount=1/(1+wacc)**(i+1);return{revenue:r,ebitda,ebit,tax,da,capex,deltaNwc,ufcf,discount,pv:ufcf*discount};});
 const last=years.at(-1), terminal=last.ufcf*(1+terminalGrowth)/(wacc-terminalGrowth), terminalPv=terminal*last.discount, enterpriseValue=years.reduce((s,y)=>s+y.pv,0)+terminalPv, equityValue=enterpriseValue+netCash;
 return {years,terminal,terminalPv,enterpriseValue,equityValue,price:equityValue/shares,terminalConcentration:terminalPv/enterpriseValue,bridgeCheck:Math.abs(enterpriseValue+netCash-equityValue)<1e-8};
}
export function runway({openingCash,monthlyRevenue,monthlyPayroll,monthlyOpex,months=36,growth=.025}){let cash=openingCash;const schedule=[];for(let m=1;m<=months;m++){const revenue=monthlyRevenue*(1+growth)**(m-1),burn=monthlyPayroll+monthlyOpex-revenue;cash-=burn;schedule.push({month:m,revenue,burn,cash});}return{schedule,runway:schedule.find(x=>x.cash<0)?.month-1??months,endingCash:cash,breakEven:schedule.find(x=>x.burn<=0)?.month??null};}
export function financing({preMoney,investment,founders,employees,existingInvestors=0,optionPoolTopUp=0}){const preTotal=founders+employees+existingInvestors;const newInvestor=investment/(preMoney+investment);const poolEffect=optionPoolTopUp*(1-newInvestor);const residual=1-newInvestor-poolEffect;return{founders:founders/preTotal*residual,employees:employees/preTotal*residual,existingInvestors:existingInvestors/preTotal*residual,newInvestor,optionPool:poolEffect,total:1};}
export const moic=(proceeds,invested)=>proceeds/invested;
export const irr=(proceeds,invested,years)=>(proceeds/invested)**(1/years)-1;
export function reverseRevenue(targetEV,base){let lo=1,hi=1e6;for(let i=0;i<80;i++){const mid=(lo+hi)/2;const ev=dcf({...base,revenue:mid}).enterpriseValue;if(ev<targetEV)lo=mid;else hi=mid;}return(lo+hi)/2;}
export function sensitivity(base,waccs,growths){return growths.map(g=>waccs.map(w=>dcf({...base,wacc:w,terminalGrowth:g}).enterpriseValue));}
export function seededSimulation(seed,count,base){let x=seed;const rand=()=>((x=Math.imul(1664525,x)+1013904223>>>0)/2**32);return Array.from({length:count},()=>dcf({...base,wacc:base.wacc+(rand()-.5)*.02,terminalGrowth:base.terminalGrowth+(rand()-.5)*.01,growths:base.growths.map(g=>g+(rand()-.5)*.08)}).enterpriseValue).sort((a,b)=>a-b);}
export function validate(model){const issues=[];if(model.wacc<=model.terminalGrowth)issues.push({level:'error',message:'WACC must exceed terminal growth'});if(model.terminalConcentration>.8)issues.push({level:'warning',message:'Terminal value exceeds 80% of enterprise value'});return issues;}
export function attribution(base,scenario,fn){const start=fn(base),items=[];let state={...base};for(const key of Object.keys(scenario)){const next={...state,[key]:scenario[key]},value=fn(next);items.push({key,impact:value-fn(state)});state=next;}const end=fn({...base,...scenario}),residual=end-start-items.reduce((s,x)=>s+x.impact,0);return{start,end,items,residual};}
